1	export const protocolVersion = 1;
2	
3	/**
4	 * Split `total` cents into `count` integer shares.
5	 * @param {number} total - nonnegative safe integer, in cents
6	 * @param {number} count - positive safe integer, <= 1000
7	 * @returns {number[]} count integer shares summing to total, differing by at most one;
8	 *   the first (total % count) shares are one cent larger.
9	 */
10	export function splitCents(total, count) {
11	  if (!Number.isSafeInteger(total) || total < 0) {
12	    throw new RangeError('total must be a nonnegative safe integer');
13	  }
14	  if (!Number.isSafeInteger(count) || count < 1 || count > 1000) {
15	    throw new RangeError('count must be a positive safe integer <= 1000');
16	  }
17	  // Avoid JS division precision loss on large `total`: (total >> 10) < 2^43,
18	  // so (total>>10)/count rounds within ~1 of true quotient; refine via exact int ops.
19	  const q10 = Math.floor((total >> 10) / count); // exact integer for (total>>10)/count to nearest
20	  let base = q10 * 1024;
21	  while ((base + 1) * count <= total) base += 1;
22	  while (base * count > total) base -= 1;
23	  const remainder = total - base * count; // total % count, exact
24	  const shares = Array.from({length: count}, () => base);
25	  for (let i = 0; i < remainder; i++) {
26	    shares[i] += 1;
27	  }
28	  return shares;
29	}
