1	export const protocolVersion = 1;
2	
3	/**
4	 * Split `total` cents into `count` integer shares.
5	 * @param {number} total - nonnegative safe integer, in cents
6	 * @param {number} count - positive safe integer, <= 1000
7	 * @returns {number[]} count integer shares summing to total, differing by at most one;
8	 *   the first (total % count) shares are one cent larger.
9	 */
10	export function splitCents(total, count) {
11	  if (!Number.isSafeInteger(total) || total < 0) {
12	    throw new RangeError('total must be a nonnegative safe integer');
13	  }
14	  if (!Number.isSafeInteger(count) || count < 1 || count > 1000) {
15	    throw new RangeError('count must be a positive safe integer <= 1000');
16	  }
17	  // Avoid JS division precision loss on large `total`: (total >> 10) < 2^43,
18	  // so (total>>10)/count rounds within ~1 of true quotient; refine via exact int ops.
19	  const q10 = Math.floor((total >> 10) / count); // exact integer for (total>>10)/count to nearest
20	  let base = q10 * 1024;
21	  while ((base + 1) * count <= total) base += 1;
22	  while (base * count > total) base -= 1;
23	  const remainder = total - base * count; // total % count, exact
24	  const shares = Array.from({length: count}, () => base);
25	  for (let i = 0; i < remainder; i++) {
26	    shares[i] += 1;
27	  }
28	  return shares;
29	}
30

1	import {test} from 'node:test';
2	import assert from 'node:assert/strict';
3	import {splitCents, protocolVersion} from '../src/shares.mjs';
4	
5	test('protocolVersion is preserved', () => {
6	  assert.equal(protocolVersion, 1);
7	});
8	
9	test('exact division', () => {
10	  assert.deepEqual(splitCents(100, 4), [25, 25, 25, 25]);
11	});
12	
13	test('remainder goes to earliest indices', () => {
14	  assert.deepEqual(splitCents(10, 3), [4, 3, 3]);
15	  assert.deepEqual(splitCents(7, 4), [2, 2, 2, 1]);
16	});
17	
18	test('zero total', () => {
19	  assert.deepEqual(splitCents(0, 5), [0, 0, 0, 0, 0]);
20	});
21	
22	test('single share gets everything', () => {
23	  assert.deepEqual(splitCents(12345, 1), [12345]);
24	});
25	
26	test('sum is preserved and max-min <= 1', () => {
27	  for (const [total, count] of [[1, 1000], [999, 999], [1000000, 1000]]) {
28	    const shares = splitCents(total, count);
29	    assert.equal(shares.length, count);
30	    assert.ok(shares.every((s) => Number.isInteger(s)));
31	    assert.equal(shares.reduce((a, b) => a + b, 0), total);
32	    assert.ok(Math.max(...shares) - Math.min(...shares) <= 1);
33	    const extra = total % count;
34	    for (let i = 0; i < count - 1; i++) {
35	      assert.equal(shares[i] - shares[i + 1], i < extra ? 1 : 0);
36	    }
37	  }
38	  // Independent check of the big case
